// Client-side extractor for full Google Maps URLs (no network call needed)
function extractGoogleMapsCoords(url) {
    const atMatch = url.match(/@(-?\d+\.?\d*),(-?\d+\.?\d*)/);
    if (atMatch) return {
        lat: parseFloat(atMatch[1]),
        lng: parseFloat(atMatch[2])
    };
    const qMatch = url.match(/[?&]q=(-?\d+\.?\d*),(-?\d+\.?\d*)/);
    if (qMatch) return {
        lat: parseFloat(qMatch[1]),
        lng: parseFloat(qMatch[2])
    };
    const llMatch = url.match(/[?&]ll=(-?\d+\.?\d*),(-?\d+\.?\d*)/);
    if (llMatch) return {
        lat: parseFloat(llMatch[1]),
        lng: parseFloat(llMatch[2])
    };
    const embedMatch = url.match(/!3d(-?\d+\.?\d*)!4d(-?\d+\.?\d*)/);
    if (embedMatch) return {
        lat: parseFloat(embedMatch[1]),
        lng: parseFloat(embedMatch[2])
    };
    return null;
}
